; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; 13: Cls
			dw kw_cls

			; 14: Print "VB self test 11"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 17: Chk Add3(10), 13
			dw fn_add3, lit_10, var_add3_add3
			dw p_chk_c, var_add3_add3, lit_13

			; 18: a = 20
			dw kw_ltov, 20, var_a

			; 19: Chk Add3(a), 23
			dw fn_add3, var_a, var_add3_add3
			dw p_chk_c, var_add3_add3, lit_23

			; 20: Chk Add3(a * 2) + Add3(1), 47
			dw kw_2x, var_a, tmp0
			dw fn_add3, tmp0, var_add3_add3
			dw kw_vtov, var_add3_add3, tmp0
			dw fn_add3, lit_1, var_add3_add3
			dw kw_vtov, var_add3_add3, tmp1
			dw kw_add, tmp0, tmp1, tmp0
			dw p_chk_c, tmp0, lit_47

			; 21: Chk Add3(Add3(Add3(0))), 9
			dw fn_add3, lit_0, var_add3_add3
			dw kw_vtov, var_add3_add3, tmp0
			dw fn_add3, tmp0, var_add3_add3
			dw kw_vtov, var_add3_add3, tmp0
			dw fn_add3, tmp0, var_add3_add3
			dw p_chk_c, var_add3_add3, lit_9

			; 24: a = Add3(5)
			dw fn_add3, lit_5, var_a

			; 25: Chk a, 8
			dw p_chk_c, var_a, lit_8

			; 26: a = Add3(a)
			dw fn_add3, var_a, var_add3_add3
			dw kw_vtov, var_add3_add3, var_a

			; 27: Chk a, 11
			dw p_chk_c, var_a, lit_11

			; 30: Chk AddXY(7, 8), 15
			dw fn_addxy, lit_7, lit_8, var_addxy_addxy
			dw p_chk_c, var_addxy_addxy, lit_15

			; 31: b = AddXY(a, 5) * 2
			dw fn_addxy, var_a, lit_5, var_addxy_addxy
			dw kw_vtov, var_addxy_addxy, tmp0
			dw kw_2x, tmp0, var_b

			; 32: Chk b, 32
			dw p_chk_c, var_b, lit_32

			; 35: c = 41
			dw kw_ltov, 41, var_c

			; 36: Inc c
			dw fn_inc, var_c

			; 37: Chk c, 42
			dw p_chk_c, var_c, lit_42

			; 38: Inc c
			dw fn_inc, var_c

			; 39: Inc c
			dw fn_inc, var_c

			; 40: Chk c, 44
			dw p_chk_c, var_c, lit_44

			; 43: s = "hello"
			dw kw_strcpy, var_s, str1

			; 44: UpFirst s
			dw fn_upfirst, var_s

			; 45: Chk Asc(s), 72
			dw kw_strasc, var_s, tmp0
			dw p_chk_c, tmp0, lit_72

			; 46: Chk Len(s), 5
			dw kw_strlen, var_s, tmp0
			dw p_chk_c, tmp0, lit_5

			; 49: n = Big(3)
			dw fn_big, lit_3, var_n

			; 50: Chk n \ 65536, 3
			dw kw_l_div, var_n, llit_65536, ltmp0
			dw kw_l_ltoi, ltmp0, tmp0
			dw p_chk_c, tmp0, lit_3

			; 51: Chk n Mod 65536, 0
			dw kw_l_mod, var_n, llit_65536, ltmp0
			dw kw_l_ltoi, ltmp0, tmp0
			dw p_chk_c, tmp0, lit_0

			; 54: Chk AddC(1), 4
			dw fn_addc, lit_1, var_addc_addc
			dw p_chk_c, var_addc_addc, lit_4

			; 57: Chk Twice(21), 42
			dw p_twice_c, lit_21
			dw p_chk_c, var_twice_twice, lit_42

			; 60: c = 0
			dw kw_ztov, var_c

			; 61: For i = 1 To 50
			dw kw_ltov, 1, var_i
for1_t:

			; 62: Inc c
			dw fn_inc, var_c

			; 63: Next
			dw kw_next1l_n, var_i, 50, for1_t
for1_e:

			; 64: Chk c, 50
			dw p_chk_c, var_c, lit_50

			; 66: Print
			dw kw_printnl

			; 67: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printstrvar, str2
			dw kw_printint, var_bad
			dw kw_printstrvar, str3
			dw kw_printnl

			; 68: Print "Press a key";
			dw kw_printstrvar, str4

			; 69: Do : Frame : Loop Until Inkey <> 0
do2_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_t
do2_e:

			; 70: Print
			dw kw_printnl

			; 71: End
			dw kw_stop

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 74: t = t + 1
			dw kw_inc, var_t

			; 75: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str5

			; 76: If got = want Then
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if3_1

			; 77: Print "ok ";
			dw kw_printstrvar, str6

			; 78: Else
			dw if3_e_go
if3_1:

			; 79: Print "FAIL("; got; ") ";
			dw kw_printstrvar, str7
			dw kw_printint, var_chk_got
			dw kw_printstrvar, str8

			; 80: bad = bad + 1
			dw kw_inc, var_bad

			; 81: End If
if3_e:
			dw p_chk_r

; ============================================================
; function twice (normal mode)
; ============================================================

p_twice:

			; 179: #asm
			dw asm_0_179_n
			dw p_twice_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if3_e_go:			ld sp, if3_e
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_twice_c:		; call twice (normal)
			pop hl			; x
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_twice_x), de
			ld hl, 0
			ld (var_twice_twice), hl
			ld (p_twice_rs), sp
			ld sp, p_twice
			jp ntc_xn
p_twice_r:		; end of twice
			ld sp, (p_twice_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_add3:		; function add3 (asm keyword), main.bas line 85
    pop hl          ; address of x [86]
    ld e,(hl)		; main.bas 87
    inc hl		; main.bas 88
    ld d,(hl)		; main.bas 89
    inc de		; main.bas 90
    inc de		; main.bas 91
    inc de		; main.bas 92
    pop hl          ; address of the result [93]
    ld (hl),e		; main.bas 94
    inc hl		; main.bas 95
    ld (hl),d		; main.bas 96
			ret			; end of #asm

fn_addxy:		; function addxy (asm keyword), main.bas line 101
    pop hl          ; x [102]
    ld e,(hl)		; main.bas 103
    inc hl		; main.bas 104
    ld d,(hl)		; main.bas 105
    pop hl          ; y [106]
    ld a,(hl)		; main.bas 107
    inc hl		; main.bas 108
    ld h,(hl)		; main.bas 109
    ld l,a		; main.bas 110
    add hl,de		; main.bas 111
    ex de,hl		; main.bas 112
    pop hl          ; result [113]
    ld (hl),e		; main.bas 114
    inc hl		; main.bas 115
    ld (hl),d		; main.bas 116
			ret			; end of #asm

fn_inc:		; sub inc (asm keyword), main.bas line 121
    pop hl          ; address of v (ByRef: write through it) [122]
    inc (hl)		; main.bas 123
    jr nz,fn_inc_done		; main.bas 124
    inc hl		; main.bas 125
    inc (hl)		; main.bas 126
fn_inc_done:		; main.bas 127
			ret			; end of #asm

fn_upfirst:		; sub upfirst (asm keyword), main.bas line 132
    pop hl          ; the string itself (0 terminated) [133]
    ld a,(hl)		; main.bas 134
    cp 'a'		; main.bas 135
    ret c		; main.bas 136
    cp 'z'+1		; main.bas 137
    ret nc		; main.bas 138
    sub 32		; main.bas 139
    ld (hl),a		; main.bas 140
			ret			; end of #asm

fn_big:		; function big (asm keyword), main.bas line 145
    pop hl          ; hi [146]
    ld e,(hl)		; main.bas 147
    inc hl		; main.bas 148
    ld d,(hl)		; main.bas 149
    pop hl          ; result: 4 bytes, low word first [150]
    xor a		; main.bas 151
    ld (hl),a		; main.bas 152
    inc hl		; main.bas 153
    ld (hl),a		; main.bas 154
    inc hl		; main.bas 155
    ld (hl),e		; main.bas 156
    inc hl		; main.bas 157
    ld (hl),d		; main.bas 158
			ret			; end of #asm

fn_addc:		; function addc (asm keyword), main.bas line 163
    pop hl		; main.bas 164
    ld e,(hl)		; main.bas 165
    inc hl		; main.bas 166
    ld d,(hl)		; main.bas 167
    ld hl,3		; main.bas 168
    add hl,de		; main.bas 169
    ex de,hl		; main.bas 170
    pop hl		; main.bas 171
    ld (hl),e		; main.bas 172
    inc hl		; main.bas 173
    ld (hl),d		; main.bas 174
			ret			; end of #asm

asm_0_179_n:		; #asm, main.bas line 179 (normal)
    ld hl,(var_twice_x)		; main.bas 180
    add hl,hl		; main.bas 181
    ld (var_twice_twice),hl		; main.bas 182
			ret			; end of #asm


; ============================================================
; Variables
; ============================================================

var_add3_add3:			dw 0
var_a:			dw 0
var_addxy_addxy:			dw 0
var_b:			dw 0
var_c:			dw 0
			db 40			; capacity
var_s:			ds 41
var_n:			dw 0, 0
var_addc_addc:			dw 0
var_twice_twice:			dw 0
var_i:			dw 0
var_t:			dw 0
var_bad:			dw 0
p_chk_rs:			dw 0
var_chk_got:			dw 0
var_chk_want:			dw 0
p_twice_rs:			dw 0
var_twice_x:			dw 0
tmp0:			dw 0
tmp1:			dw 0
ltmp0:			dw 0, 0

; numbers passed by address (read only)
lit_10:			dw 10
lit_13:			dw 13
lit_23:			dw 23
lit_1:			dw 1
lit_47:			dw 47
lit_0:			dw 0
lit_9:			dw 9
lit_5:			dw 5
lit_8:			dw 8
lit_11:			dw 11
lit_7:			dw 7
lit_15:			dw 15
lit_32:			dw 32
lit_42:			dw 42
lit_44:			dw 44
lit_72:			dw 72
lit_3:			dw 3
llit_65536:			dw 0, 1
lit_4:			dw 4
lit_21:			dw 21
lit_50:			dw 50

; ============================================================
; Strings
; ============================================================

str0:			db "VB self test 11", 0
str1:			db "hello", 0
str2:			db " tests, ", 0
str3:			db " failed", 0
str4:			db "Press a key", 0
str5:			db ":", 0
str6:			db "ok ", 0
str7:			db "FAIL(", 0
str8:			db ") ", 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_next1l_n:	jp 31
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_inc:		jp 51
kw_add:		jp 53
kw_2x:		jp 57
kw_cpeqvv:	jp 95
kw_cpnevl:	jp 98
kw_strcpy:	jp 122
kw_strlen:	jp 125
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl:	jp 138
kw_inkey:	jp 144
kw_cls:		jp 147
kw_frame:	jp 152
kw_strasc:	jp 185
kw_l_ltoi:	jp 208
kw_l_div:	jp 229
kw_l_mod:	jp 230
NTC_RJ_N	equ 24		; entries
ntc_csp	equ #8800		; ROM data
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #894E		; ROM data
ntc_v_romen	equ #8954		; ROM data
ntc_v_romold	equ #8956		; ROM data
ntc_v_stamp	equ #8952		; ROM data
ntc_v_start	equ #8950		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM set in slots 0 - 31 (its main ROM, then the others with the same
; stamp), have the main one patch the jump block. NC = ready; C = not there / too old
; (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			xor a
			ld (ntc_rj_want), a
			call ntc_rj_scan		; the main ROM
			jp c, ntc_rj_nf
			ld (ntc_rj_slots), a
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, 1
ntc_rj_more:				; the other ROMs of the set
			ld (ntc_rj_want), a
			ld hl, ntc_rj_n
			cp (hl)
			jr nc, ntc_rj_all
			call ntc_rj_scan
			jp c, ntc_rj_part
			ld b, a
			ld a, (ntc_rj_want)
			ld e, a
			ld d, 0
			ld hl, ntc_rj_slots
			add hl, de
			ld (hl), b
			inc a
			jr ntc_rj_more
ntc_rj_all:
			ld a, (ntc_rj_slots)
			ld c, a
			call #B90F		; KL ROM SELECT: the main ROM
			di					; (KL ROM SELECT lets interrupts in)
			ld a, (ntc_rj_slots)	; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
			ld de, ntc_rj_slots
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot, DE = slots; C: DE = a number it hasn't got
			jp c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
; ntc_rj_scan - a ROM of the set: ROM ntc_rj_want (0 = the main one, any stamp; the others
; with the main one's stamp). NC: A = its slot, HL = past its block's count byte (the main
; one: at its patcher), it is selected. C: not there
ntc_rj_scan:
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its set's stamp
			inc hl
			ld a, (ntc_rj_want)
			cp (hl)				; its place in the set
			jr nz, ntc_rj_skip
			or a
			jr z, ntc_rj_got
			push hl
			ld hl, (ntc_rj_set)
			or a
			sbc hl, de
			pop hl
			jr nz, ntc_rj_skip		; another build's
ntc_rj_got:
			ld (ntc_rj_set), de
			inc hl
			ld a, (hl)
			ld (ntc_rj_n), a		; ROMs in the set
			inc hl
			ld a, c
			or a				; NC
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			scf					; C: not there
			ret
ntc_rj_nf:
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_part:				; a ROM of the set is missing: its number (1 = the main one)
			ld a, (ntc_rj_want)
			inc a
			ld e, a
			ld d, 0
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tpt
			jr ntc_rj_fnum
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fnum:
			ld a, 1
			ld (ntc_rj_pn), a		; the number after the message
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld a, (ntc_rj_pn)
			or a
			jr z, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_pn:		db 0			; 1 = a number goes after the message
ntc_rj_want:	db 0			; the ROM of the set looked for
ntc_rj_n:		db 1			; ROMs in the set
ntc_rj_set:		dw 0			; the set's stamp
ntc_rj_slots:	ds 8			; each ROM's slot, the main one first
ntc_rj_sig:		db "NTC", 2, "CPCFW", 0	; the ROMs' NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCFW (NTCFW.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCFW too old: no routine #", 0
ntc_rj_tpt:		db "ROM NTCFW<n>.ROM not found: n = #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "VBTEST11.BIN", ntc_start, ntc_end - ntc_start, ntc_start
